mapper.sql:
WHERE f20.`adjustflag` = #{adjustFlag} AND f20.`horizon_days` = 20

    AND f20.`trade_date` = #{tradeDate}
    AND f20.`trade_date` = (SELECT MAX(x.`trade_date`) FROM `stock_forecast_daily` x WHERE x.`adjustflag` = #{adjustFlag} AND x.`horizon_days` = 20)

AND (f20.`code` LIKE CONCAT('%',#{keyword},'%') OR i.`name` LIKE CONCAT('%',#{keyword},'%'))
AND f20.`target15_probability` >= #{minProbability}

mapper.select:
SELECT DISTINCT `trade_date` FROM `stock_forecast_daily`
WHERE `adjustflag`=#{adjustFlag} AND `horizon_days`=20
ORDER BY `trade_date` DESC LIMIT #{limit}
